# Checks the samples folder of an install (<prefix>/samples, or <prefix>/share/blitzllvm/samples in the packages), given as the argument:
# the samples of BlitzLLVM and the originals of Blitz3D and BlitzPlus are there, and nothing that may not be redistributed is.
# Media/geometricks_models of the original Blitz3D is such a folder: its license does not allow passing it on, so no file of it may be shipped.
set -u
samples="$1"
failed=0
for d in tutorials games original-blitz3d/samples original-blitz3d/Games original-blitz3d/tutorials original-blitzplus/samples original-blitzplus/games; do
	if [ ! -d "$samples/$d" ]; then
		echo "error: the samples have no $d" >&2
		failed=1
	fi
done
forbidden=$(find "$samples" -ipath '*geometricks*')
if [ -n "$forbidden" ]; then
	echo "error: files of Media/geometricks_models, which may not be redistributed, are in the samples:" >&2
	echo "$forbidden" >&2
	failed=1
fi
exit $failed
